class _FilterClause:
    """A single parsed comparison within a filter string."""

    def __init__(self, entity_type: str, key: str, comparator: str, value: Any):
        self.entity_type = entity_type  # "attribute" or "tag"
        self.key = key
        self.comparator = comparator.upper()
        self.value = value


def _strip_quotes(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] in ("'", '"') and value[-1] == value[0]:
        return value[1:-1]
    if len(value) >= 2 and value[0] == "`" and value[-1] == "`":
        return value[1:-1]
    return value


def _like_to_regex(pattern: str) -> str:
    # Translate an SQL LIKE pattern (with % and _) into a regular expression.
    result = ["^"]
    for ch in pattern:
        if ch == "%":
            result.append(".*")
        elif ch == "_":
            result.append(".")
        else:
            result.append(re.escape(ch))
    result.append("$")
    return "".join(result)


def _parse_mcp_filter(filter_string: str | None) -> list[_FilterClause]:
    """Parse an AND-ed filter string into a list of comparison clauses."""
    if not filter_string or not filter_string.strip():
        return []

    # Split on top-level ``AND`` (the supported filters never contain a nested AND).
    parts = re.split(r"\s+AND\s+", filter_string.strip(), flags=re.IGNORECASE)
    clauses: list[_FilterClause] = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        clauses.append(_parse_single_comparison(part))
    return clauses


def _parse_single_comparison(expr: str) -> _FilterClause:
    # Handle ``key IN (v1, v2, ...)`` first.
    in_match = re.match(r"^(?P<key>[^\s]+)\s+IN\s+\((?P<vals>.*)\)\s*$", expr, flags=re.IGNORECASE)
    if in_match:
        key = in_match.group("key")
        raw_values = in_match.group("vals")
        values = [_strip_quotes(v) for v in raw_values.split(",") if v.strip()]
        entity_type, parsed_key = _classify_key(key)
        return _FilterClause(entity_type, parsed_key, "IN", values)

    comp_match = re.match(
        r"^(?P<key>[^\s=!<>]+)\s*(?P<op>>=|<=|!=|=|>|<|LIKE|ILIKE)\s*(?P<value>.+)$",
        expr,
        flags=re.IGNORECASE,
    )
    if not comp_match:
        raise MlflowException(
            f"Invalid filter expression '{expr}'", error_code=INVALID_PARAMETER_VALUE
        )
    key = comp_match.group("key")
    op = comp_match.group("op")
    raw_value = comp_match.group("value").strip()
    entity_type, parsed_key = _classify_key(key)
    # Numeric values are left unquoted; string values are quoted.
    if entity_type == "attribute" and re.fullmatch(r"-?\d+(\.\d+)?", raw_value):
        value: Any = float(raw_value) if "." in raw_value else int(raw_value)
    else:
        value = _strip_quotes(raw_value)
    return _FilterClause(entity_type, parsed_key, op, value)


def _classify_key(key: str) -> tuple[str, str]:
    key = key.strip()
    if key.lower().startswith("tags.") or key.lower().startswith("tag."):
        _, _, tag_key = key.partition(".")
        return "tag", _strip_quotes(tag_key)
    return "attribute", _strip_quotes(key)


